const providers={siliconflow:{name:'硅基流动',console:'https://cloud.siliconflow.cn/',docs:'https://docs.siliconflow.cn/docs/userguide/quickstart',price:'https://www.siliconflow.cn/pricing',base:'https://api.siliconflow.cn/v1'},deepseek:{name:'DeepSeek',console:'https://platform.deepseek.com/',docs:'https://api-docs.deepseek.com/',price:'https://api-docs.deepseek.com/quick_start/pricing/',base:'https://api.deepseek.com'},openai:{name:'OpenAI',console:'https://platform.openai.com/',docs:'https://developers.openai.com/api/docs/quickstart',price:'https://developers.openai.com/api/docs/pricing',base:'https://api.openai.com/v1'}};
function questionPreview(){if(state.profile.built||state.model.source!=='off')return baseQuestionPreview();saveQuestion();openDialog('保留背景，使用中性起点','<p>AI 尚未启用，问卷回答和跳过情况都已保存。</p><p class="quote">13 维属性暂按 50 未评估，启动资金 80 币。以后可补充背景；不会因为补评再次发启动资金。</p>',()=>{if(!state.profile.built){state.profile.built=true;state.profile.evaluated=false;state.profile.initial=80;ledger(80,'中性基线 · 一次性启动资金','startup','起点')}save();closeDialog();go('my')},'确认中性起点')}
function modelStatus(m){return ({ready:'模拟测试通过',unverified:'已保存 · 尚未测试',failed:'测试失败',testing:'正在测试'})[m.status]||'尚未配置'}
function modelsPage(){const m=editedModel(),d=modelDraft||m;return back('my')+heading('模型与 AI','看清当前绑定的模型，也能区分保存和测试。')+`<div class="subnav"><button class="btn ${state.modelTarget!=='aux'?'soft':''}" data-full="model-group" data-id="primary">判定模型</button><button class="btn ${state.modelTarget==='aux'?'soft':''}" data-full="model-group" data-id="aux">辅助回顾模型</button></div><div class="two-col"><section class="card"><h2>${state.modelTarget==='aux'?'辅助回顾':'判定'} · 当前已保存配置</h2><p class="quote"><strong>${esc(modelCaption(m))}</strong><br>${m.source==='off'?'不发起分析':esc(modelStatus(m))}</p>${state.modelTarget==='aux'?`<p class="small muted">${state.auxModel?'独立辅助配置':'当前沿用判定模型'}</p><button class="text-button" data-full="aux-follow">沿用判定模型</button>`:''}<div class="row wrap"><button class="btn ${m.source==='own'?'soft':''}" data-full="model-source" data-id="own">使用自己的模型</button><button class="btn ${m.source==='off'?'soft':''}" data-full="model-source" data-id="off">关闭 AI</button></div><p class="note mt">站点共享模型按之前讨论暂不启用。无模型也能保存记录、写日记、安排计划和导出。</p><a href="#model-help" class="text-button mt">第一次配置？查看步骤与官方入口 →</a></section><section class="card"><h2>编辑个人配置</h2><label class="field">供应商<select id="model-provider">${Object.entries(providers).map(([k,p])=>`<option value="${k}" ${d.provider===k?'selected':''}>${p.name}</option>`).join('')}<option value="custom" ${d.provider==='custom'?'selected':''}>其他兼容接口</option></select></label><label class="field">接口地址<input id="model-base" value="${esc(d.base)}" placeholder="https://…/v1"></label><label class="field">完整模型 ID<input id="model-name" value="${esc(d.model)}" placeholder="从官方模型列表复制完整 ID"></label><label class="field">API Key<input id="model-key" type="password" disabled placeholder="Demo 不收集真实密钥"></label><div class="row wrap"><button class="btn primary" data-full="save-model">保存配置</button><button class="btn" data-full="test-model">测试已保存配置</button></div>${modelDraft?'<p class="daily-note">有未保存修改，测试前请先保存。</p>':''}${m.error?`<p class="error" role="alert">${esc(m.error)}</p>`:''}<p class="daily-note">本机模拟只接受 demo-chat-model 或 example-chat。其他 ID 展示测试失败，不代表真实供应商的模型不可用。</p></section></div>`}
function modelHelp(){return back('models')+heading('配置自己的 API','先取得官方接口信息，再保存和测试。')+`<section class="card"><ol class="steps-list"><li>进入供应商官方控制台，查看可用模型与自己的使用权限。</li><li>复制完整模型 ID、兼容接口地址，并在正式系统填写自己的 API Key。</li><li>保存后，核对页面上的供应商、模型和状态，再点击测试。</li><li>若失败，检查模型 ID、余额／配额、权限与地址。保存成功不等于模型可用。</li></ol><p class="note mt">是否有免费额度、哪些模型免费及使用限制，以官方页面为准；此 Demo 不承诺永久免费服务。</p></section><div class="three-col mt">${Object.values(providers).map(p=>`<section class="card"><h3>${p.name}</h3><p class="small muted mt">复制完整模型 ID，不能用聊天产品昵称替代 API 模型名。</p><div class="stack mt"><a href="${p.console}" target="_blank" rel="noopener noreferrer">官方控制台 ↗</a><a href="${p.docs}" target="_blank" rel="noopener noreferrer">配置文档 ↗</a><a href="${p.price}" target="_blank" rel="noopener noreferrer">价格与额度 ↗</a></div></section>`).join('')}</div>`}
function securityPage(){return back('my')+heading('账号与安全','密码、邮箱和设备都在这里管理。')+`<div class="two-col"><section class="card"><h2>我的账号</h2><div class="list-row"><span>用户名</span><strong>${esc(state.account.username)}</strong></div><div class="list-row"><span>邮箱</span><span>${esc(state.account.email)}</span></div><div class="list-row"><span>邮箱状态</span><span class="tag ${state.account.verified?'green':''}">${state.account.verified?'已验证 · 示例':'待验证'}</span></div><div class="row wrap mt"><button class="btn" data-full="change-password">修改密码</button><button class="btn" data-full="change-email">更换邮箱</button></div><p class="daily-note">所有密码操作都是模拟，不存储密码、不发送真实邮件。</p></section><section class="card"><h2>设备与恢复</h2><div class="list-row"><span>当前浏览器</span><span class="tag green">当前设备</span></div><div class="list-row"><span>其他设备</span><span>${state.account.otherDevices} 个示例会话</span></div><div class="row wrap mt"><button class="btn" data-full="logout-devices" ${!state.account.otherDevices?'disabled':''}>退出其他设备</button><button class="text-button" data-full="forgot-password">忘记密码 →</button><button class="text-button" data-full="logout">退出登录体验</button></div></section></div>`}
function authPage(){const register=authMode==='register',forgot=authMode==='forgot';return back('my')+`<section class="card auth-card"><div class="eyebrow">游戏人生 · LifeXP</div><h1>${forgot?'找回密码':register?'给自己留一页':'欢迎回来'}</h1><p class="subtitle">${forgot?'使用已验证邮箱恢复账号。':register?'直接注册，不需要邀请码。':'普通账号与管理账号分别进入各自工作区。'}</p><p class="note mt">本机模拟，不创建真实账号、不发送邮件。示例密码不会保存。</p>${forgot?'<label class="field">邮箱<input id="auth-email" type="email" value="lin@example.com"></label>':`${register?'<label class="field">用户名<input id="auth-username" value="new_preview_friend" maxlength="30"></label><label class="field">邮箱<input id="auth-email" type="email" value="preview@example.com"></label>':'<label class="field">用户名<input id="auth-username" value="xiaolin"></label><label class="field">体验身份<select id="auth-role"><option value="user">普通账号</option><option value="admin">管理账号</option></select></label>'}<label class="field">示例密码<input id="auth-password" type="password" value="demo-password-123" autocomplete="off"></label>${register?'<label class="field">再次填写示例密码<input id="auth-confirm" type="password" value="demo-password-123" autocomplete="off"></label>':''}`}<p id="auth-error" class="error" role="alert"></p><button class="btn primary full" data-full="auth-submit">${forgot?'模拟发送重设链接':register?'体验注册':'进入体验'}</button><div class="row between wrap mt"><button class="text-button" data-full="auth-mode" data-id="${register?'login':'register'}">${register?'已有账号，去登录':'创建账号'}</button><button class="text-button" data-full="auth-mode" data-id="forgot">忘记密码</button></div></section>`}
function changePassword(admin=false){openDialog(admin?'修改管理账号密码':'修改密码','<label class="field">当前示例密码<input id="current-password" type="password" value="demo-password-123" autocomplete="off"></label><label class="field">新示例密码<input id="new-password" type="password" value="demo-new-password-123" autocomplete="off"></label><label class="field">确认新示例密码<input id="confirm-password" type="password" value="demo-new-password-123" autocomplete="off"></label><p class="daily-note">演示校验与确认，不存储这些输入。</p>',()=>{const old=$('#current-password').value,a=$('#new-password').value,b=$('#confirm-password').value;if(!old||a.length<12||a!==b)return failDialog('填写当前密码，新密码至少 12 个字符，且两次一致。');if(admin)adminLog('修改管理密码','lifexp_admin','管理身份主动修改');else state.account.passwordChanged=state.day;save();closeDialog();toast('示例密码修改流程已完成。')},'确认修改')}
function announcementsPage(){const n=state.noticeData;return back('my')+heading('站点公告','管理员发布后，会同步出现在首页。')+`<section class="card">${n.published?`<span class="tag green">已发布 · v${n.version}</span><h2 class="mt">${esc(n.title)}</h2><p class="detail-original mt">${esc(n.body)}</p>`:'<p class="empty">目前没有已发布公告。</p>'}</section>`}
function exportPage(){const o=exportDraft;return back('my')+heading('导出与本地保存','选择原文、完整辅助记录或游戏存档。')+`<div class="two-col"><section class="card"><label class="field">文件格式<select id="export-format">${[['markdown','Markdown · 阅读与整理'],['html','HTML · 浏览器离线阅读'],['json','JSON · 完整业务存档'],['csv','CSV · 原文表格']].map(([v,n])=>`<option value="${v}" ${o.format===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">记录范围<select id="export-kind">${[['all','事件与日记'],['event','只导出事件'],['diary','只导出日记']].map(([v,n])=>`<option value="${v}" ${o.kind===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="form-grid"><label class="field">开始日期<input id="export-start" type="date" value="${o.start}"></label><label class="field">结束日期<input id="export-end" type="date" value="${o.end}"></label></div><label class="check-option"><input id="export-ai" type="checkbox" ${o.ai?'checked':''}>包含 AI 问题、我的回答与分析</label><label class="check-option"><input id="export-game" type="checkbox" ${o.game?'checked':''} ${o.format!=='json'?'disabled':''}>包含金币、属性、计划、成就、奖励券（JSON）</label><div class="row wrap mt"><button class="btn" data-full="preview-export">预览内容</button><button class="btn primary" data-full="download-export">下载文件</button></div><p id="export-error" class="error"></p></section><section class="card"><h2>这份文件里有什么？</h2><p class="quote">日记原文、AI 引导问题、你的回答、辅助分析分别标注，不把 AI 内容冒充原文。</p><p class="small muted">Markdown / HTML 适合本地阅读；JSON 保存结构化业务数据；CSV 适合表格查看。不会导出密钥、密码或管理员用户列表。</p><p class="note mt">导出不等于已支持恢复导入。旧真实数据迁移仍单独办理。</p></section></div><pre id="export-preview" class="export-preview card mt" hidden></pre>`}
function readExport(){return {format:$('#export-format').value,kind:$('#export-kind').value,start:$('#export-start').value,end:$('#export-end').value,ai:$('#export-ai').checked,game:$('#export-game').checked}}
function makeExport(o){if(!o.start||!o.end||o.start>o.end)throw Error('请选择有效的开始和结束日期。');const rows=state.records.filter(r=>r.contentDay>=o.start&&r.contentDay<=o.end&&(o.kind==='all'||r.kind===o.kind)).map(r=>({id:r.id,type:r.kind,savedDay:r.savedDay,contentDay:r.contentDay,original:r.text,version:r.version,revoked:!!r.revoked,...(o.ai?{supplement:r.supplement||'',eventAnalysis:r.confirmedSnapshot||r.suggestion||null,reviewSessions:r.sessions}:{} )}));const game={coins:state.coins,ledger:state.ledger,attributes:Object.fromEntries(dimensions.map(n=>[n,attributeValue(n)])),goals:state.goals,plans:state.plans,outcomes:state.outcomes,achievements:state.claims,products:state.products,vouchers:state.vouchers,timers:state.timers,challenges:state.challenges};const transcript=r=>r.reviewSessions?.map(s=>s.turns.map(t=>'AI 问题：'+t.question+'\n我的回答：'+(t.state==='skipped'?'已跳过':t.answer||'尚未回答')).join('\n\n')+(s.analysis?'\nAI 辅助分析：'+s.analysis:'')).join('\n\n')||'';if(o.format==='json')return {name:'LifeXP-本地存档.json',mime:'application/json;charset=utf-8',text:JSON.stringify({schema:'lifexp-demo-v1',exportedDay:state.day,records:rows,...(o.game?{game}:{})},null,2)};if(o.format==='html')return {name:'LifeXP-离线日记.html',mime:'text/html;charset=utf-8',text:'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>LifeXP 离线记录</title><style>body{max-width:760px;margin:36px auto;padding:24px;font:16px/1.9 sans-serif;color:#273249}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{border-bottom:1px solid #ddd;padding:20px 0}</style><h1>我的 LifeXP 记录</h1>'+rows.map(r=>`<article><h2>${r.contentDay} · ${r.type==='diary'?'日记':'事件'}</h2><h3>我的原文</h3><pre>${esc(r.original)}</pre>${o.ai?'<h3>辅助记录</h3><pre>'+esc(transcript(r)+(r.eventAnalysis?'\n事件分析：'+JSON.stringify(r.eventAnalysis):''))+'</pre>':''}</article>`).join('')+'</html>'};if(o.format==='csv'){const cell=x=>{let t=String(x??'');if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'};return {name:'LifeXP-记录.csv',mime:'text/csv;charset=utf-8',text:'\uFEFF'+[['类型','内容所属日','实际保存日','我的原文',...(o.ai?['完整辅助记录']:[])],...rows.map(r=>[r.type,r.contentDay,r.savedDay,r.original,...(o.ai?[JSON.stringify({review:r.reviewSessions,event:r.eventAnalysis})]:[])])].map(a=>a.map(cell).join(',')).join('\r\n')}}return {name:'LifeXP-日记.md',mime:'text/markdown;charset=utf-8',text:'# 我的 LifeXP 记录\n\n'+rows.map(r=>`## ${r.contentDay} · ${r.type==='diary'?'日记':'事件'}\n\n### 我的原文\n\n${r.original}\n\n${o.ai?'### 辅助记录\n\n'+transcript(r)+(r.eventAnalysis?'\n\n事件分析：'+JSON.stringify(r.eventAnalysis):''):''}`).join('\n\n---\n\n')}}
function downloadFile(file){const url=URL.createObjectURL(new Blob([file.text],{type:file.mime})),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
